const SOURCES = { instagram: 'Instagram', ig: 'Instagram', insta: 'Instagram', 'instagram ad': 'Instagram', facebook: 'Facebook', fb: 'Facebook',
  whatsapp: 'WhatsApp', outreach: 'Outreach', email: 'Outreach', referral: 'Referral', website: 'Website', event: 'Event' };
const TYPES = ['restaurant', 'hotel', 'caterer', 'household'];
const STAGES = { 'new enquiry': 'New enquiry', 'tasting booked': 'Tasting booked', 'proposal sent': 'Proposal sent', 'trial order': 'Trial order', won: 'Won', lost: 'Lost' };
const OWNERS = ['Tolu', 'Bisi'];
const phoneFix = (p) => { const d = String(p || '').replace(/\D/g, '').replace(/^(234|0)/, ''); return d.length === 10 ? '+234' + d : ''; };
const domainFix = (w) => String(w || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const out = [], problems = [];
const seenEmail = new Set(), companies = new Map();
let people = 0;
for (const { json: r } of $input.all()) {
  const row = r.row_number;
  const role = String(r.role || '').toLowerCase();
  const email = String(r.email || '').trim().toLowerCase();
  if (['staff', 'supplier', 'test'].includes(role) || /test|example\.com$/.test(email)) { problems.push({ row, problem: `removed: ${role || 'test row'}` }); continue; }
  if (email && seenEmail.has(email)) { problems.push({ row, problem: `duplicate email ${email}` }); continue; }
  if (email) seenEmail.add(email);
  const source = SOURCES[String(r.lead_source || '').trim().toLowerCase()];
  if (!source) problems.push({ row, problem: `lead_source "${r.lead_source}" is not a dropdown value` });
  const type = String(r.business_type || '').trim().toLowerCase();
  if (!TYPES.includes(type)) problems.push({ row, problem: `business_type "${r.business_type}" is not a dropdown value` });
  let consent = String(r.marketing_consent || '').trim().toLowerCase();
  if (!['yes', 'no'].includes(consent)) consent = 'unknown';
  if (consent === 'yes' && !r.consent_date) { consent = 'unknown'; problems.push({ row, problem: 'consent yes without a date: set to unknown (a WhatsApp contact is not email consent)' }); }
  const domain = domainFix(r.website);
  if (r.company && !domain) problems.push({ row, problem: `company "${r.company}" has no domain` });
  const batch = people < 10 ? 'batch 1 (first 10)' : 'batch 2';
  people++;
  if (domain && !companies.has(domain)) {
    companies.set(domain, true);
    out.push({ record_type: 'company', batch, name: r.company, domain, business_type: TYPES.includes(type) ? type : '', delivery_zone: String(r.delivery_zone || '').toLowerCase() === 'in' ? 'in' : 'out' });
  }
  out.push({ record_type: 'contact', batch, firstname: String(r.name || '').split(' ')[0], lastname: String(r.name || '').split(' ').slice(1).join(' '),
    email, phone: phoneFix(r.phone), company_domain: domain, lead_source: source || '', marketing_consent: consent, consent_date: consent === 'yes' ? r.consent_date : '' });
  const stage = STAGES[String(r.deal_stage || '').trim().toLowerCase()];
  if (r.deal_stage && !stage) problems.push({ row, problem: `deal_stage "${r.deal_stage}" is not one of the 5 stages` });
  if (stage) {
    const open = !['Won', 'Lost'].includes(stage);
    if (open && !OWNERS.includes(r.owner)) problems.push({ row, problem: 'open deal without an owner (Tolu or Bisi)' });
    if (open && !r.next_step_date) problems.push({ row, problem: 'open deal without a next step date' });
    if (stage === 'Lost' && !r.lost_reason) problems.push({ row, problem: 'lost deal without a lost reason' });
    out.push({ record_type: 'deal', batch, dealname: `${r.company || r.name} · weekly supply`, dealstage: stage, weekly_value_ngn: Number(String(r.weekly_value_ngn || '').replace(/[^\d]/g, '')) || '',
      hubspot_owner: r.owner || '', next_step_date: r.next_step_date || '', lost_reason: r.lost_reason || '', company_domain: domain, contact_email: email });
  }
}
return [...out, ...problems.map(p => ({ record_type: 'problem', ...p }))].map(j => ({ json: j }));
